import { createRemoteJWKSet, jwtVerify } from 'jose';

// 1. JWKS 远程公钥：设缓存 TTL 和冷却期防轮换日大批量刷新
const JWKS = createRemoteJWKSet(
  new URL('https://auth.example.com/.well-known/jwks.json'),
  { cooldownDuration: 30_000, cacheMaxAge: 600_000 }
);

async function verifyAccessToken(token) {
  // 2. jwtVerify 一次性完成：算法白名单 + kid 取公钥 + 签名 + 标准声明
  const { payload, protectedHeader } = await jwtVerify(token, JWKS, {
    issuer: 'https://auth.example.com',   // iss 严格匹配
    audience: 'api://orders',              // aud 必须包含本服务
    algorithms: ['RS256', 'ES256'],        // alg 白名单，拒绝 alg=none 和 HS256 混淆
    clockTolerance: 30                     // 时钟偏差容忍 30 秒
  });

  // 3. 业务 scope 检查：验签通过 ≠ 有权限
  const scopes = (payload.scope ?? '').split(' ');
  if (!scopes.includes('orders.read')) {
    throw new Error('insufficient_scope');
  }

  // 4. jti 黑名单：登出/封禁时写入 Redis，TTL=剩余 exp
  if (await isJtiRevoked(payload.jti)) {
    throw new Error('token_revoked');
  }

  return payload;
}

